def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def nth_prime(n):
    """Find the nth prime number (1-indexed)"""
    if n == 1:
        return 2
    count = 1
    candidate = 3
    while count < n:
        if is_prime(candidate):
            count += 1
        if count < n:
            candidate += 2
    return candidate

